int check_stack_boundary(struct bpf_verifier_env *env, int regno, int access_size, bool zero_size_allowed, struct bpf_call_arg_meta *meta)
{
    struct bpf_reg_state *reg = &env->cur_state->regs[regno];
    int off, i, err;

    if (reg->type != PTR_TO_STACK)
        return -EACCES;

    if (access_size == 0) {
        if (zero_size_allowed)
            return 0;
        return -EACCES;
    }

    off = reg->off;
    if (off < 0 && off + access_size > 0)
        return -EACCES;

    if (off != reg->off)
        return -EACCES;

    for (i = 0; i < access_size; i++) {
        int slot = -off - i - 1;
        if (slot >= BPF_STACK_DEPTH)
            return -EACCES;
    }

    env->cur_state->allocated_stack = max(env->cur_state->allocated_stack, -off + access_size);
    return 0;
}

int check_stack_boundary_access(struct bpf_verifier_env *env, int regno,
                                int access_size, bool zero_size_allowed,
                                struct bpf_call_arg_meta *meta)
{
    struct bpf_reg_state *reg = &env->cur_state->regs[regno];
    int i, off, slot_off;

    if (reg->type != PTR_TO_STACK)
        return -EACCES;

    if (access_size == 0) {
        if (zero_size_allowed)
            return 0;
        return -EACCES;
    }

    if (reg->off != 0)
        return -EACCES;

    off = reg->off + reg->var_off.value;
    if (off + access_size > MAX_BPF_STACK || off < 0)
        return -EACCES;

    for (i = 0; i < access_size; i++) {
        slot_off = off + i;
        if (slot_off % BPF_REG_SIZE != 0)
            continue;
        if (env->cur_state->allocated_stack < slot_off + BPF_REG_SIZE)
            return -EACCES;
    }

    return 0;
}

int check_stack_boundary_access(struct bpf_verifier_env *env, int regno, int access_size,
                                bool zero_size_allowed, struct bpf_call_arg_meta *meta)
{
    struct bpf_reg_state *reg = &env->cur_state->regs[regno];
    int i, slot, offset, err = 0;

    if (reg->type != PTR_TO_STACK)
        return -EACCES;

    /* Allow zero-size access if permitted */
    if (access_size == 0 && zero_size_allowed)
        return 0;

    if (reg->off + access_size < reg->off)
        return -EACCES;

    offset = reg->off;
    if (offset < 0)
        return -EACCES;

    for (i = 0; i < access_size; i++) {
        slot = offset + i;
        if (slot >= BPF_MAX_STACK_DEPTH)
            return -EACCES;
    }

    env->cur_state->stack_depth = max(env->cur_state->stack_depth, offset + access_size);

    return 0;
}

int check_stack_boundary_access(struct bpf_verifier_env *env, int regno, int access_size,
                                bool zero_size_allowed, struct bpf_call_arg_meta *meta)
{
    struct bpf_reg_state *regs = cur_regs(env);
    struct bpf_reg_state *reg = &regs[regno];
    int i, off, slot;

    if (reg->type != PTR_TO_STACK) {
        return -EACCES;
    }

    if (access_size == 0) {
        if (zero_size_allowed) {
            return 0;
        }
        return -EACCES;
    }

    if (reg->off < 0) {
        return -EACCES;
    }

    off = reg->off;
    for (i = 0; i < access_size; i++) {
        slot = -(off + i) / BPF_REG_SIZE;
        if (slot < 0 || slot >= MAX_BPF_STACK / BPF_REG_SIZE) {
            return -EACCES;
        }
    }

    if (meta) {
        meta->stack_depth = max(meta->stack_depth, off + access_size);
    }

    return 0;
}

int check_stack_boundary_access(struct bpf_verifier_env *env, int regno, int access_size,
                                bool zero_size_allowed, struct bpf_call_arg_meta *meta)
{
    struct bpf_reg_state *reg = &env->cur_state->regs[regno];
    int i;

    if (reg->type != PTR_TO_STACK)
        return -EACCES;

    if (access_size == 0 && zero_size_allowed)
        return 0;

    if (access_size <= 0)
        return -EACCES;

    if (reg->off != 0 && reg->off != -1) {
        if (reg->off >= 0)
            return -EACCES;
        if (reg->off + access_size > 0)
            return -EACCES;
    }

    for (i = 0; i < access_size; i++) {
        int off = reg->off + i;
        if (off >= MAX_BPF_STACK || off < 0)
            return -EACCES;
    }

    if (reg->off + access_size > env->cur_state->allocated_stack)
        env->cur_state->allocated_stack = reg->off + access_size;

    return 0;
}
